function homeBalance() { return S.hide ? '<span class="display"><small>Rp</small>•••••••</span>' : `<span class="display"><small>Rp</small>${Math.round(S.bal).toLocaleString("id-ID")}</span>`; }
V.home = () => {
  const empty0 = S.tx.length === 0, loading = S.data === "loading", err = S.data === "error";
  const top = `<div class="hdr" style="padding-top:0"><button class="av" onclick="go('profile')" aria-label="Akun">R</button><div class="grow"></div><button class="pill-info" onclick="go('promo')" aria-label="Voucher">${ic("gift", "sm")} 3</button><button class="rb" onclick="go('notif')" aria-label="Notifikasi">${ic("bell")}${S.data === "full" ? '<span class="bd">2</span>' : ""}</button></div>`;
  const greet = `<h1 class="title" style="font-size:34px;letter-spacing:-.04em;margin-top:14px">Selamat malam, Rina.</h1><div class="flex mt8" style="color:var(--mute);font:600 15px var(--font)">Hari ini · Sabtu, 14 November <button onclick="toggleHide()" aria-label="Tampilkan atau sembunyikan saldo" style="margin-left:2px">${ic(S.hide ? "eyeoff" : "eye", "sm")}</button></div>`;
  let amount;
  if (loading) amount = '<div class="skel" style="height:56px;width:220px;margin-top:22px"></div><div class="skel" style="height:16px;width:260px;margin-top:14px"></div>';
  else if (err) amount = `<div class="note danger" style="margin-top:22px;background:rgba(255,255,255,.85)">${ic("warn")}<div><b>Saldo belum dapat dimuat</b>Periksa koneksi lalu coba lagi. Saldo dan transaksimu tidak berubah.<br><button class="linkbtn" style="margin-top:8px;font-weight:600" onclick="setData('full')">Coba lagi</button></div></div>`;
  else amount = `<div style="margin-top:18px">${homeBalance()}</div><div class="sub mt8" style="font-size:15px">${empty0 ? "Bilang “pulsa 25rb” atau scan QR." : "Bulan ini keluar " + rp(838900) + " · <span style='color:var(--ok);font-weight:600'>turun 12%</span>"}</div>`;
  const ask = `<button class="ask" onclick="sheet('ask')" aria-label="Tanya Yumi"><img src="assets/icons/business-ai-assistant.webp" alt=""><span>Tanya Yumi apa saja</span><i class="go">${ic("up")}</i></button>`;
  const tiles = `<div class="tile3"><button class="tile t-peach" onclick="go('promo')">${I3("promo-voucher", 52)}<span class="chip2">3 voucher</span><span>Promo</span></button><button class="tile t-mint" onclick="go('summary')">${I3("sales-report", 52)}<span>Ikuti uangmu</span></button><button class="tile t-lav" onclick="go('bills')">${I3("order-receipt", 52)}<span>Tagihan rutin</span></button></div>`;
  const quick = `<div class="quick">${[["pulsa", "Pulsa"], ["data", "Data"], ["pln", "Token PLN"], ["pln-bill", "Tagihan"]].map(([k, l]) => { const s = SERVICES.find((x) => x[0] === k); return `<button class="q" onclick="openSvc('${k}')"><span class="qi c-${s[4]}">${ic(s[3], "lg")}</span>${l}</button>`; }).join("")}<button class="q" onclick="sheet('all')"><span class="qi" style="background:var(--group);color:var(--navy)">${ic("grid", "lg")}</span>Lainnya</button></div>`;
  const today = `<div class="group" style="margin-top:22px;display:flex;align-items:center;gap:12px;padding:14px 14px"><span class="ico" style="width:44px;height:44px;border-radius:50%;background:#fff;display:grid;place-items:center;color:var(--navy)">${ic("cal")}</span><div style="flex:1"><div class="sub">Hari ini</div><b style="font-size:17px;white-space:nowrap">${empty0 ? "Belum ada transaksi" : "Keluar " + rp(25400)}</b></div>${empty0 ? `<button class="btn sm" onclick="go('topup')">Isi saldo</button>` : `<button class="btn sm" style="background:var(--group);color:var(--navy);box-shadow:0 0 0 1px var(--line)" onclick="tab('history')">Lihat</button>`}</div>`;
  const next = empty0 ? `<div class="sec" style="margin-top:24px"><h2>Berikutnya</h2></div><div style="display:flex;gap:10px;overflow-x:auto;margin:0 -18px;padding:0 18px 4px;scrollbar-width:none"><button class="group flex" style="flex:none;width:250px" onclick="go('topup')"><span class="cat c-blue">${ic("down")}</span><span style="text-align:left"><b>Isi saldo pertama</b><div class="sub">Mulai dari Rp 20.000</div></span></button><button class="group flex" style="flex:none;width:250px" onclick="go('security')"><span class="cat c-emerald">${ic("face")}</span><span style="text-align:left"><b>Aktifkan Face ID</b><div class="sub">Masuk lebih cepat</div></span></button></div>` : `<div class="sec"><h2>Aktivitas terbaru</h2><button onclick="tab('history')">Lihat semua</button></div><div class="group flush">${S.tx.slice(0, 3).map(txRow).join("")}</div>`;
  return { html: sky(`<div class="pad" style="padding-bottom:0">${top}${greet}${loading ? amount : amount}${ask}<div class="body-sheet">${loading ? '<div class="skel" style="height:112px;margin-bottom:12px"></div><div class="skel" style="height:80px"></div>' : tiles + quick + today + next}</div></div>`), tabs: 1 };
};
V.services = () => ({ tabs: 1, html: sky(`<div class="pad"><div class="hdr" style="padding-top:0"><h1 class="page-title" style="text-align:left;font-size:32px;flex:1">Layanan</h1><button class="rb" onclick="go('bills')" aria-label="Tagihan rutin">${ic("repeat")}</button></div><div class="search mt8">${ic("search", "sm")}<input placeholder="Cari layanan atau nomor" aria-label="Cari layanan"></div><div class="glabel">Semua layanan</div><div class="group white"><div class="tile3" style="gap:6px 8px;grid-template-columns:repeat(3,1fr)">${SERVICES.map((s) => `<button class="q" style="padding:8px 0" onclick="openSvc('${s[0]}')"><span class="qi c-${s[4]}" style="width:56px;height:56px;border-radius:20px;display:grid;place-items:center">${ic(s[3], "lg")}</span><span style="font-size:13px;font-weight:600">${s[1]}</span>${s[5] === "off" ? '<span class="tag" style="margin-top:-4px">Segera</span>' : ""}</button>`).join("")}</div></div><div class="glabel">Nomor tersimpan</div><div class="group flush">${rowI({ t: "Rina — 0812-3456-7890", s: "Telkomsel · pulsa & data", col: "blue", ic: "user", go: "openSvc('pulsa',{n:'081234567890'})" })}${rowI({ t: "Rumah — Meter 5432 1098 76", s: "PLN prabayar", col: "amber", ic: "flash", go: "openSvc('pln')" })}</div><div class="glabel">Terakhir dibeli</div><div class="group flush">${rowI({ t: "Pulsa 25.000", s: "Hari ini · 0812-3456-7890", col: "blue", ic: "phone", tr: "Beli lagi", go: "openSvc('pulsa',{n:'081234567890'})", nochev: 1 })}${rowI({ t: "Token PLN 100 rb", s: "Kemarin · Meter 5432 1098 76", col: "amber", ic: "flash", tr: "Beli lagi", go: "openSvc('pln')", nochev: 1 })}</div><div class="group" style="background:linear-gradient(135deg,#e1ecff,#c9dcff);margin-top:16px;display:flex;align-items:center;gap:12px"><div style="flex:1"><span class="tag info">PROMO</span><div class="title" style="font-size:19px;margin-top:6px">Cashback 10% token PLN</div><div class="sub">Sampai 30 Nov · min. Rp 50.000</div></div>${I3("promo-voucher", 76)}</div></div>`) });

/* ppob */
const catName = { pulsa: "Pulsa", data: "Paket Data", pln: "Token PLN", game: "Voucher Game", "pln-bill": "Tagihan PLN", pdam: "Tagihan PDAM", bpjs: "BPJS", tv: "TV & Streaming", multifinance: "Cicilan" };
V.ppob = () => {
  const c = S.p.cat, list = PRODUCTS[c] || [], isPhone = c === "pulsa" || c === "data", num = S.ppob.number, op = isPhone ? opOf(num) : "", valid = isPhone ? num.replace(/\D/g, "").length >= 10 && op && !op.startsWith("Operator tidak") : num.replace(/\D/g, "").length >= (c === "pln" ? 11 : 4);
  const label = isPhone ? "Nomor HP tujuan" : c === "pln" ? "Nomor meter / ID pelanggan" : "ID pemain";
  const sel = S.ppob.sel >= 0 ? list[S.ppob.sel] : null;
  const grid = c === "pulsa" || c === "pln" ? "prodgrid" : "prodlist";
  const prods = list.map((p, i) => `<button class="prod ${S.ppob.sel === i ? "on" : ""}" onclick="pickProd(${i})"><span><b>${p.n}</b><span>${p.d}</span></span>${grid === "prodlist" ? `<span class="price">${rp(p.p)}</span>` : ""}</button>`).join("");
  const priceRow = grid === "prodgrid" ? list.map((p, i) => "").join("") : "";
  return { html: sky(`<div class="pad nobar" style="padding-bottom:150px">${hdr({ title: catName[c] })}<div class="field" style="margin-top:6px"><span>${label}</span><div class="input">${isPhone ? ic("phone", "sm") : c === "pln" ? ic("flash", "sm") : ic("game", "sm")}<input id="inp-num" inputmode="numeric" placeholder="${isPhone ? "0812 3456 7890" : c === "pln" ? "5432 1098 76" : "Masukkan ID"}" value="${num}" oninput="S.ppob.number=this.value;render(false)">${op && !op.startsWith("Operator tidak") ? `<span class="tag info">${op}</span>` : ""}${num ? `<button onclick="S.ppob.number='';S.ppob.sel=-1;render(false)" aria-label="Hapus">${ic("close", "sm")}</button>` : `<button class="linkbtn" onclick="S.ppob.number='081234567890';render(false)">Nomorku</button>`}</div>${op.startsWith("Operator tidak") ? '<div class="hint err">Nomor tidak dikenali. Periksa kembali awalan nomornya.</div>' : isPhone ? '<div class="hint">Operator terdeteksi otomatis dari awalan nomor.</div>' : c === "pln" && valid ? '<div class="hint ok">Meter dikenali · RINA M. · 1300 VA</div>' : ""}</div><div class="glabel">${c === "pulsa" ? "Pilih nominal" : "Pilih produk"}</div>${valid ? `<div class="${grid}">${prods}</div>` : `<div class="note info">${ic("info")}<div>Masukkan ${label.toLowerCase()} untuk melihat produk yang tersedia.</div></div>`}</div>${sel && valid ? `<div class="sticky"><div class="spread" style="margin:0 6px 10px"><span class="sub">${sel.n}</span><b style="font-size:18px">${rp(sel.p)}</b></div><button class="btn" onclick="payPpob()">Lanjut bayar</button></div>` : ""}`) };
};
V.post = () => {
  const c = S.p.cat, inq = S.post.inq, no = S.post.no, valid = no.replace(/\D/g, "").length >= 11;
  return { html: sky(`<div class="pad nobar" style="padding-bottom:140px">${hdr({ title: catName[c] })}<div class="field" style="margin-top:6px"><span>Nomor pelanggan</span><div class="input">${ic("receipt", "sm")}<input id="inp-no" inputmode="numeric" placeholder="5432 1098 76" value="${no}" oninput="S.post.no=this.value;S.post.inq=false;render(false)"></div>${valid ? "" : '<div class="hint">Masukkan 11–12 digit nomor pelanggan.</div>'}</div>${inq ? `<div class="glabel">Detail tagihan</div><div class="group white">${kv([["Nama pelanggan", "RINA MAHARANI"], ["Periode", "Oktober 2026"], ["Tarif / daya", "R1 / 1300 VA"], ["Tagihan", rp(248600)], ["Biaya admin", rp(2500)], ["Total bayar", rp(251100), "total"]])}</div><div class="note info">${ic("info")}<div>Tagihan diambil langsung dari penyedia. Total sudah termasuk biaya admin.</div></div>` : ""}</div><div class="sticky"><button class="btn ${valid ? "" : "off"}" onclick="${inq ? "payPost()" : "S.post.inq=true;render(false)"}">${inq ? "Bayar " + rp(251100) : "Cek tagihan"}</button></div>`) };
};
V.unavail = () => ({ html: sky(`<div class="pad nobar">${hdr({ title: catName[S.p.cat] })}${empty("restaurant-cafe", "Belum tersedia", "Layanan ini sedang disiapkan. Saldo dan transaksimu tidak akan berubah.", `<button class="btn inline" style="margin-top:14px" onclick="toast('Kami kabari saat tersedia')">Kabari saya</button>`)}</div>`) });

/* result */
V.result = () => {
  const f = S.flow || {}, st = f.status || "ok", svg = st === "ok" ? IC.check : st === "pending" ? IC.clock : IC.close;
  const ttl = st === "ok" ? f.okTitle || "Pembayaran berhasil" : st === "pending" ? "Sedang diproses" : "Pembayaran gagal", sub2 = st === "ok" ? f.okSub || "Bukti transaksi sudah disimpan di Riwayat." : st === "pending" ? "Saldo tetap aman. Jangan kirim ulang sampai status berubah — kami kabari lewat notifikasi." : "Saldo tidak terpotong. Periksa koneksi atau coba lagi sebentar lagi.";
  return { html: sky(`<div class="pad nobar" style="padding-bottom:150px"><div class="center" style="margin-top:34px"><div class="success-ring ${st === "ok" ? "" : st === "pending" ? "warn" : "bad"}"><svg viewBox="0 0 24 24">${svg}</svg></div><h1 class="title">${ttl}</h1><div class="money" style="margin-top:8px">${rp(f.total || 0)}</div><p class="sub" style="margin:8px auto 0;max-width:290px;font-size:14px">${sub2}</p></div>${st === "ok" && f.sn ? `<div class="group white mt" style="text-align:center"><div class="sub">No. token PLN</div><div style="font:700 24px var(--font);letter-spacing:.04em;color:var(--navy);margin:6px 0;font-variant-numeric:tabular-nums">${f.sn}</div><button class="btn sm soft" onclick="toast('Token disalin')">${ic("copy", "sm")} Salin token</button></div>` : ""}<div class="group white mt">${kv((f.rows || []).concat([["Waktu", "14 Nov 2026 · 19.41"], ["ID transaksi", "DP-261114-0847"]]))}</div>${st === "pending" ? `<div class="note">${ic("clock")}<div><b>Estimasi 1–5 menit</b>Status akan diperbarui otomatis di Riwayat.</div></div>` : ""}</div><div class="sticky">${st === "failed" ? `<button class="btn" onclick="sheet('confirm')">Coba lagi</button><button class="btn soft" style="margin-top:10px" onclick="goHome()">Kembali ke Beranda</button>` : `<button class="btn" onclick="goHome()">Selesai</button>${st === "ok" ? `<button class="btn ghost" style="margin-top:10px" onclick="toast('Bukti dibagikan')">${ic("share", "sm")} Bagikan bukti</button>` : ""}`}</div>`) };
};

/* topup / qris */
V.topup = () => {
  const amt = S.top.custom ? +S.top.custom.replace(/\D/g, "") : S.top.amt, ok = amt >= 20000;
  return { html: sky(`<div class="pad nobar" style="padding-bottom:140px">${hdr({ title: "Isi saldo" })}<div class="center"><div class="sub">Saldo saat ini</div><div class="money" style="font-size:22px">${rp(S.bal)}</div></div><div class="bigamt"><b>Rp</b><input id="inp-amt" inputmode="numeric" placeholder="0" value="${amt ? amt.toLocaleString("id-ID") : ""}" oninput="S.top.custom=this.value.replace(/\\D/g,'');S.top.amt=0;render(false)"></div><div class="${ok || !amt ? "hint" : "hint err"} center">${ok || !amt ? "Minimal Rp 20.000" : "Minimal isi saldo Rp 20.000"}</div><div class="amt-presets">${[20000, 50000, 100000, 200000, 500000, 1000000].map((v) => `<button class="preset ${amt === v ? "on" : ""}" onclick="S.top.amt=${v};S.top.custom='';render(false)">${v >= 1e6 ? "1 jt" : v / 1000 + " rb"}</button>`).join("")}</div><div class="glabel">Metode pembayaran</div><div class="opt on"><span class="cat c-blue sq">${ic("qr")}</span><span class="main"><b>QRIS</b><span>Mayar · semua bank & e-wallet</span></span><span class="radio"></span></div><div class="note info">${ic("info")}<div>Saldo masuk otomatis setelah pembayaran QRIS terkonfirmasi.</div></div></div><div class="sticky"><div class="spread" style="margin:0 6px 10px"><span class="sub">Total bayar</span><b style="font-size:18px">${rp(amt || 0)}</b></div><button class="btn ${ok ? "" : "off"}" onclick="startTopup(${amt})">Lanjut ke QRIS</button></div>`) };
};
V.qris = () => ({ html: sky(`<div class="pad nobar" style="padding-bottom:150px">${hdr({ title: "Bayar dengan QRIS" })}<div class="center"><div class="sub">Total pembayaran</div><div class="money">${rp(S.p.amt || S.flow?.total || 0)}</div><div class="flex" style="justify-content:center;margin-top:6px"><span class="tag warn">${ic("clock", "sm")} Berlaku 14:52</span></div></div><div class="qrbox mt">${qrSvg(73)}</div><p class="sub center" style="margin:14px 30px 0">Buka aplikasi bank atau e-wallet, pilih <b>Scan QRIS</b>, lalu pindai kode ini.</p><div class="group white mt"><div class="flex"><div class="spin" style="width:18px;height:18px;border-width:2.5px"></div><div><b style="font-size:14.5px">Menunggu pembayaran</b><div class="sub">Status diperiksa otomatis tiap 5 detik.</div></div></div></div></div><div class="sticky"><button class="btn" onclick="qrisPaid()">Saya sudah bayar (demo)</button><button class="btn soft" style="margin-top:10px" onclick="back()">Batalkan pembayaran</button></div>`) });

/* send */
V.send = () => { const s = S.send, ok = s.name; return { html: sky(`<div class="pad nobar" style="padding-bottom:140px">${hdr({ title: "Kirim saldo" })}<div class="seg"><button class="on">Sesama Djiwa Pay</button><button onclick="go('withdraw')">Ke rekening bank</button></div><div class="field"><span>Nomor HP penerima</span><div class="input">${ic("phone", "sm")}<input id="inp-ph" inputmode="numeric" placeholder="0857 1122 3344" value="${s.phone}" oninput="S.send.phone=this.value;S.send.name='';render(false)"><button class="btn sm" style="min-height:36px" onclick="checkRecipient()">Cek</button></div>${ok ? `<div class="note ok" style="margin-top:10px">${ic("check")}<div><b>${s.name}</b>Terverifikasi · Djiwa Pay</div></div>` : '<div class="hint">Tekan Cek untuk memastikan nama penerima sebelum kirim.</div>'}</div><div class="glabel">Terakhir dikirimi</div><div class="group flush">${rowI({ t: "Budi Santoso", s: "0857-1122-3344", col: "violet", ic: "user", go: "pickRecipient('0857-1122-3344','Budi Santoso')" })}${rowI({ t: "Sari Wulandari", s: "0813-9988-7766", col: "emerald", ic: "user", go: "pickRecipient('0813-9988-7766','Sari Wulandari')" })}</div></div><div class="sticky"><button class="btn ${ok ? "" : "off"}" onclick="go('send-amount')">Lanjut</button></div>`) }; };
V["send-amount"] = () => { const s = S.send, amt = +String(s.amt).replace(/\D/g, ""), ok = amt >= 10000 && amt <= S.bal; return { html: sky(`<div class="pad nobar" style="padding-bottom:140px">${hdr({ title: "Nominal kirim" })}<div class="group white flex" style="margin-top:6px"><span class="av" style="background:var(--blue-soft)">${s.name[0]}</span><div><b>${s.name}</b><div class="sub">${s.phone}</div></div></div><div class="bigamt"><b>Rp</b><input id="inp-amt" inputmode="numeric" placeholder="0" value="${amt ? amt.toLocaleString("id-ID") : ""}" oninput="S.send.amt=this.value.replace(/\\D/g,'');render(false)"></div><div class="${amt > S.bal ? "hint err" : "hint"} center">${amt > S.bal ? "Saldo tidak cukup. Isi saldo dulu." : "Saldo tersedia " + rp(S.bal) + " · min. Rp 10.000"}</div><div class="field"><span>Catatan <em>opsional</em></span><div class="input"><input placeholder="Contoh: bayar makan siang" value="${s.note}" oninput="S.send.note=this.value"></div></div></div><div class="sticky"><button class="btn ${ok ? "" : "off"}" onclick="sheet('send-confirm')">Tinjau & kirim</button></div>`) }; };
/* withdraw */
V.withdraw = () => { const w = S.wd, amt = +String(w.amt).replace(/\D/g, ""), ok = w.acc.length >= 8 && w.name && amt >= 50000 && amt + 2500 <= S.bal; return { html: sky(`<div class="pad nobar" style="padding-bottom:140px">${hdr({ title: "Tarik dana" })}<div class="center"><div class="sub">Saldo dapat ditarik</div><div class="money" style="font-size:22px">${rp(S.bal)}</div></div><div class="field"><span>Bank tujuan</span><div class="input"><select id="inp-bank" onchange="S.wd.bank=this.value">${BANKS.map((b) => `<option ${w.bank === b ? "selected" : ""}>${b}</option>`).join("")}</select></div></div><div class="field"><span>Nomor rekening</span><div class="input"><input id="inp-acc" inputmode="numeric" placeholder="1234567890" value="${w.acc}" oninput="S.wd.acc=this.value;render(false)"></div></div><div class="field"><span>Nama pemilik rekening</span><div class="input"><input id="inp-nm" placeholder="Sesuai buku tabungan" value="${w.name}" oninput="S.wd.name=this.value;render(false)"></div></div><div class="field"><span>Nominal penarikan</span><div class="input"><b>Rp</b><input id="inp-wa" inputmode="numeric" placeholder="50.000" value="${amt ? amt.toLocaleString("id-ID") : ""}" oninput="S.wd.amt=this.value.replace(/\\D/g,'');render(false)"></div><div class="hint">Minimal Rp 50.000 · biaya Rp 2.500 · diproses maks. 1×24 jam.</div></div></div><div class="sticky"><button class="btn ${ok ? "" : "off"}" onclick="sheet('withdraw-confirm')">Tinjau penarikan</button></div>`) }; };
V["withdraw-pending"] = () => { S.flow = { status: "pending", total: 502500, rows: [["Bank tujuan", "BCA •••• 4821"], ["Atas nama", "Rina Maharani"], ["Nominal", rp(500000)], ["Biaya", rp(2500)]] }; return V.result(); };
V["topup-done"] = () => { S.flow = { status: "ok", total: 200000, okTitle: "Isi saldo berhasil", okSub: "Saldo bertambah otomatis.", rows: [["Metode", "QRIS Mayar"], ["Nominal", rp(200000)], ["Saldo sekarang", rp(S.bal)]] }; return V.result(); };

/* receive */
