V.scan = () => ({ dark: 1, noTabs: 1, html: `<div class="cam"><div style="position:absolute;top:56px;left:18px;right:18px" class="hdr"><button class="rb" onclick="back()" aria-label="Tutup">${ic("close")}</button><div class="grow"><h1 style="color:#fff">Scan QR</h1></div><button class="rb" onclick="toast('Senter menyala')" aria-label="Senter">${ic("flash")}</button></div><div class="frame"><i></i><i></i><i></i><i></i><div class="scanline"></div></div><div class="center" style="position:absolute;left:0;right:0;top:62%;color:rgba(255,255,255,.85);font-size:15px">Arahkan kamera ke QRIS atau QR Djiwa Pay</div><div style="position:absolute;left:18px;right:18px;bottom:44px;display:flex;flex-direction:column;gap:10px"><button class="btn" style="background:#fff;color:var(--navy)" onclick="sheet('scan-result')">Simulasikan hasil scan</button><div class="flex"><button class="btn" style="margin:0;background:rgba(255,255,255,.16)" onclick="toast('Membuka galeri')">${ic("image", "sm")} Dari galeri</button><button class="btn" style="margin:0;background:rgba(255,255,255,.16)" onclick="go('receive')">${ic("qr", "sm")} QR saya</button></div></div></div>` });

/* history */
function filteredTx() { const h = S.hist; return S.tx.filter((t) => (h.seg === "all" || (h.seg === "in" ? t.a > 0 : t.a < 0)) && (h.cat === "Semua" || t.c === h.cat) && (!h.q || (t.t + t.s).toLowerCase().includes(h.q.toLowerCase()))); }
V.history = () => { const list = filteredTx(), h = S.hist; let body = ""; if (!S.tx.length) body = empty("order-receipt", "Belum ada transaksi", "Isi saldo atau bayar tagihan pertamamu — semua tercatat rapi di sini.", `<button class="btn" style="margin-top:14px;max-width:300px" onclick="go('topup')">${ic("plus", "sm")} Isi saldo</button>`); else if (!list.length) body = empty("restaurant-cafe", "Tidak ada hasil", "Coba ubah kata kunci, periode, atau filter."); else { const days = [...new Set(list.map((t) => t.d))]; body = days.map((d) => `<div class="dayh"><span>${d}</span><span>${rp(list.filter((t) => t.d === d && t.a < 0).reduce((s, t) => s + t.a, 0))}</span></div><div class="group flush white">${list.filter((t) => t.d === d).map(txRow).join("")}</div>`).join(""); } return { tabs: 1, html: sky(`<div class="pad"><div class="hdr" style="padding-top:0"><h1 class="page-title" style="text-align:left;flex:1">Riwayat</h1><button class="rb" onclick="go('summary')" aria-label="Ringkasan">${ic("chart")}</button></div><div class="search mt8">${ic("search", "sm")}<input id="inp-q" placeholder="Cari transaksi" value="${h.q}" oninput="S.hist.q=this.value;render(false)" aria-label="Cari transaksi"></div><div class="chips mt8"><button class="chip" onclick="sheet('period')">${ic("cal", "sm")} ${h.period}</button><button class="chip ${h.cat !== "Semua" ? "on" : ""}" onclick="sheet('filter')">${ic("filter", "sm")} ${h.cat === "Semua" ? "Filter" : h.cat}</button></div><div class="seg mt8">${[["all", "Semua"], ["in", "Masuk"], ["out", "Keluar"]].map(([k, l]) => `<button class="${h.seg === k ? "on" : ""}" onclick="S.hist.seg='${k}';render(false)">${l}</button>`).join("")}</div>${body}</div>`) }; };
V.summary = () => { const cells = []; const lv = [0, 0, 2, 0, 1, 3, 0, 0, 1, 4, 0, 2, 1, 0]; for (let i = 0; i < 6; i++) cells.push('<span></span>'); const heat = Array.from({ length: 30 }, (_, i) => { const d = i + 1, fut = d > 14, l = fut ? "" : "l" + (lv[(d - 1) % lv.length] || 0 || ""); return `<div class="d ${fut ? "fut" : lv[(d - 1) % lv.length] ? "l" + lv[(d - 1) % lv.length] : ""} ${d === 14 ? "today" : ""}">${d}</div>`; }); heat.unshift(...Array(6).fill('<span></span>')); const cats = [["Pulsa & Data", 38, "blue", 318800], ["Listrik", 24, "amber", 201000], ["Transfer", 20, "violet", 167800], ["Belanja Djiwa", 18, "orange", 151000]]; return { html: sky(`<div class="pad nobar">${hdr({ title: "Ringkasan", right: `<button class="chip" style="padding:9px 14px">Bulanan</button>` })}<div class="spread" style="margin:4px 0"><button class="rb" aria-label="Bulan sebelumnya">${ic("back", "sm")}</button><b style="font-size:18px">Nov '26</b><button class="rb" style="opacity:.4" aria-label="Bulan berikutnya">${ic("chev", "sm")}</button></div><div class="mt"><div class="sub">Uang keluar</div><div class="display" style="font-size:44px"><small style="font-size:22px">Rp</small>${S.tx.length ? "838.900" : "0"}</div></div><div class="tile3 mt" style="grid-template-columns:1fr 1fr"><div class="group white"><div class="sub">Uang masuk</div><b style="font-size:20px;color:var(--ok)">${S.tx.length ? rp(500000) : "Rp 0"}</b></div><div class="group white"><div class="sub">Rata-rata / hari</div><b style="font-size:20px">${S.tx.length ? rp(59921) : "Rp 0"}</b></div></div><div class="sec"><h2>Tren harian</h2></div><div class="heatw">${["Sen", "Sel", "Rab", "Kam", "Jum", "Sab", "Min"].map((d) => `<span>${d}</span>`).join("")}</div><div class="heat">${heat.join("")}</div><div class="sec"><h2>Per kategori</h2></div><div class="group white">${S.tx.length ? cats.map((c) => `<div style="padding:8px 0"><div class="spread"><span class="flex"><span class="cat c-${c[2]}" style="width:12px;height:12px"></span><b style="font-size:14.5px">${c[0]}</b></span><span class="sub">${rp(c[3])} · ${c[1]}%</span></div><div class="bar" style="margin-top:8px"><i style="width:${c[1] * 2}%"></i></div></div>`).join("") : '<div class="sub center" style="padding:14px">Belum ada pengeluaran bulan ini.</div>'}</div></div>`) }; };

