V.wallet = () => { const e = S.bal === 0 && !S.tx.length; return { tabs: 1, html: sky(`<div class="pad"><div class="hdr" style="padding-top:0"><h1 class="page-title" style="text-align:left;flex:1">Dompet</h1><button class="rb" onclick="go('profile')" aria-label="Akun">${ic("user")}</button></div><div class="label" style="margin-top:6px">Saldo Djiwa Pay</div><div style="margin-top:4px">${homeBalance().replace("56px", "")}</div><div class="chips" style="margin-top:12px"><span class="chip" style="background:rgba(255,255,255,.9);color:var(--navy)">${e ? "Riwayatmu dimulai hari ini" : "▲ 12% dari bulan lalu"}</span></div><div class="tile3 mt" style="grid-template-columns:repeat(4,1fr);gap:8px">${[["topup", "Isi saldo", "topup"], ["send", "Kirim", "send"], ["receive", "Terima", "receive"], ["withdraw", "Tarik", "withdraw"]].map(([a, l, g]) => `<button class="q" onclick="go('${g}')"><span class="qi" style="background:#fff;box-shadow:var(--soft);width:64px;height:64px;border-radius:22px;display:grid;place-items:center">${A3(a, 40)}</span>${l}</button>`).join("")}</div><div class="group mt" style="margin-top:22px;text-align:center;${e ? "" : "display:none"}"><p class="sub" style="margin:0 10px 4px">Tautkan rekening bank untuk menarik dana dan mengisi saldo lebih cepat.</p><button class="btn" onclick="toast('Tautkan rekening')">${ic("plus", "sm")} Tambah rekening</button></div><div class="glabel">Rekening tertaut</div><div class="group flush">${e ? '<div class="sub center" style="padding:16px">Belum ada rekening tertaut.</div>' : rowI({ t: "BCA •••• 4821", s: "Rina Maharani · utama", col: "blue", ic: "bank", tr: '<span class="tag ok">Terverifikasi</span>', go: "toast('Detail rekening')" }) + rowI({ t: "Tambah rekening", s: "Bank, e-wallet", col: "slate", ic: "plus", go: "toast('Tautkan rekening')" })}</div><button class="group flex" style="width:100%;margin-top:14px;text-align:left" onclick="sheet('card')"><img src="assets/actions/card.webp" width="64" height="64" alt=""><span style="flex:1"><b style="font-size:17px">Kartu Djiwa</b><div class="sub">Kartu virtual untuk belanja online.</div></span><span class="tag">Segera</span></button><div class="sec"><h2>Dompetmu</h2><span class="sub">${rp(S.bal)}</span></div><div class="group flush">${rowI({ i3: I3("payment-wallet", 30), t: "Djiwa Pay", s: "Saldo utama", tr: `<b>${rp(S.bal)}</b>`, go: "tab('history')" })}${rowI({ i3: I3("loyalty-points", 30), t: "Poin Djiwa", s: "Tukar jadi voucher", tr: "<b>1.240 poin</b>", go: "go('promo')" })}${rowI({ i3: I3("promo-voucher", 30), t: "Voucher", s: "3 aktif", tr: "", go: "go('promo')" })}</div></div>`) }; };
