V.promo = () => ({ html: sky(`<div class="pad nobar">${hdr({ title: "Promo & voucher" })}<div class="group white flex" style="margin-top:6px">${I3("loyalty-points", 64)}<div style="flex:1"><div class="sub">Poin Djiwa</div><div class="money">1.240</div></div><button class="btn sm" onclick="toast('Tukar poin')">Tukar</button></div><div class="glabel">Voucher aktif · 3</div>${[["Cashback 10% token PLN", "Min. Rp 50.000 · s/d 30 Nov", "promo-voucher"], ["Gratis admin pulsa", "Pulsa & data · s/d 20 Nov", "customer-benefit-promo"], ["Diskon Rp 5.000 kopi", "Di Djiwa Tentram Coffee · s/d 17 Nov", "restaurant-cafe"]].map((v) => `<div class="group white flex" style="margin-bottom:10px">${I3(v[2], 56)}<div style="flex:1"><b>${v[0]}</b><div class="sub">${v[1]}</div></div><button class="btn sm soft" onclick="toast('Voucher dipakai saat bayar')">Pakai</button></div>`).join("")}</div>`) });

