/* ---------- keypad ---------- */
function dotsHtml(v) { return `<div class="dots ${S.pin.err ? "err" : ""}">${Array.from({ length: 6 }, (_, i) => `<i class="${i < v.length ? "f" : ""}"></i>`).join("")}</div>`; }
function keypad(mode) { return `<div class="pad3">${[1, 2, 3, 4, 5, 6, 7, 8, 9].map((n) => `<button onclick="pinKey('${mode}','${n}')">${n}</button>`).join("")}<button class="ghost" onclick="${mode === "pay" ? "toast('Face ID')" : "void 0"}">${mode === "pay" ? ic("face") : ""}</button><button onclick="pinKey('${mode}','0')">0</button><button onclick="pinKey('${mode}','del')" aria-label="Hapus">${ic("del")}</button></div>`; }

/* ---------- engine ---------- */
let animate = true, backAnim = false;
function render(anim) {
  const ae = document.activeElement, id = ae && ae.id, pos = ae && ae.selectionStart;
  const sc = $("#vp .view") ? $("#vp .view").scrollTop : 0;
  const key = S.view === "ppob" || S.view === "post" ? S.view : S.view;
  const v = (V[key] || V.home)();
  const showTabs = v.tabs && !v.noTabs;
  const cls = "view " + (anim === false ? "" : backAnim ? "back" : "");
  let html = `${sbar(v.dark)}<div class="${anim === false ? "view" : cls}" id="view" ${anim === false ? 'style="animation:none"' : ""}>${v.html}</div>${showTabs ? tabbar() : ""}`;
  if (S.sheet) { const f = SH[S.sheet]; html += `<div class="scrim" onclick="closeSheet()"></div><div class="sheet" role="dialog" aria-modal="true">${f ? f() : ""}</div>`; }
  if (S.toast) html += `<div class="toast" role="status">${S.toast}</div>`;
  html += '<div class="homeind"></div>';
  $("#vp").innerHTML = html; backAnim = false;
  if (anim === false && sc) $("#view").scrollTop = sc;
  if (id && $("#" + id)) { const el = $("#" + id); el.focus(); try { if (pos != null) el.setSelectionRange(pos, pos); } catch (e) {} }
  markPanel();
}
function setView(v, p) { S.view = v; S.p = p || {}; render(); }
window.go = (v, p) => { S.stack.push({ v: S.view, p: S.p, tab: S.tab }); if (v === "qris" && p) S.p = p; S.view = ["ppob", "post", "unavail"].includes(v) ? v : v; S.p = p || {}; S.sheet = null; render(); };
window.back = () => { const s = S.stack.pop(); backAnim = true; if (s) { S.view = s.v; S.p = s.p; } else { S.view = S.tab; S.p = {}; } S.sheet = null; render(); };
window.tab = (t) => { S.tab = t; S.stack = []; S.view = t; S.p = {}; S.sheet = null; render(); };
window.goHome = () => { S.stack = []; tab("home"); };
window.sheet = (n, p) => { S.sheet = n === "scan-result" ? "scanResult" : n === "ask-result" ? "ask-result" : n; S.sp = p || {}; render(false); };
window.closeSheet = () => { S.sheet = null; S.pin = { v: "", mode: "pay", first: "", err: 0 }; render(false); };
window.toast = (m) => { S.toast = m; render(false); clearTimeout(window._t); window._t = setTimeout(() => { S.toast = ""; render(false); }, 1800); };
window.toggleHide = () => { S.hide = !S.hide; render(false); };
window.setData = (m) => { S.data = m; if (m === "empty") { S.tx = []; S.bal = 0; } else if (m === "full") { S.tx = TX0.slice(); S.bal = 1250000; } else if (m === "loading" || m === "error") { S.tx = TX0.slice(); S.bal = 1250000; } render(false); };
window.openSvc = (k, o) => { const s = SERVICES.find((x) => x[0] === k); S.ppob = { number: (o && o.n) || "", sel: -1 }; S.post = { no: "", inq: false }; S.sheet = null; if (s[5] === "off") go("unavail", { cat: k }); else if (s[5] === "post") go("post", { cat: k }); else go("ppob", { cat: k }); };
window.pickProd = (i) => { S.ppob.sel = S.ppob.sel === i ? -1 : i; render(false); };
window.finishOnboard = () => { S.stack = []; S.pin = { v: "", mode: "pay", first: "" }; tab("home"); toast("Selamat datang di Djiwa Pay"); };
window.checkRecipient = () => { if (S.send.phone.replace(/\D/g, "").length >= 10) { S.send.name = "Budi Santoso"; } else toast("Nomor HP belum lengkap"); render(false); };
window.pickRecipient = (ph, nm) => { S.send.phone = ph; S.send.name = nm; render(false); };
window.askSend = () => { S.ask.text = S.ask.text || "isi pulsa 25rb ke 0812 3456 7890"; sheet("ask-result"); };
window.startTopup = (a) => { S.flow = null; go("qris", { amt: a }); };
window.qrisPaid = () => { const f = S.flow; if (f && f.method === "qris" && f.total) { S.stack = []; S.flow = Object.assign({}, f, { status: "ok" }); S.view = "result"; S.p = {}; render(); return; } S.bal += S.p.amt || 0; S.stack = []; S.view = "topup-done"; S.p = {}; render(); };
function begin(f) { S.flow = Object.assign({ method: "wallet", status: "ok" }, f); sheet("confirm"); }
window.payPpob = (cat) => { const c = cat || S.p.cat, list = PRODUCTS[c], p = list[S.ppob.sel], isP = c === "pulsa" || c === "data"; const rows = [[isP ? "Operator" : "Layanan", isP ? opOf(S.ppob.number) || "Telkomsel" : catName[c]], ["Produk", p.n], [isP ? "Nomor tujuan" : c === "pln" ? "No. meter" : "ID pemain", S.ppob.number || "081234567890"], ["Harga", rp(p.p - (c === "pulsa" ? 400 : 0))]]; if (c === "pulsa") rows.push(["Biaya admin", rp(400)]); begin({ title: p.n, total: p.p, rows, sn: c === "pln" ? "4821 7730 1948 2257 6610" : null, okTitle: c === "pln" ? "Token berhasil dibeli" : null }); };
window.payPost = () => begin({ title: "Tagihan PLN · Okt 2026", total: 251100, rows: [["Layanan", "PLN pascabayar"], ["No. pelanggan", S.post.no || "543210987612"], ["Nama", "RINA MAHARANI"], ["Tagihan", rp(248600)], ["Biaya admin", rp(2500)]] });
window.payScan = () => { const a = +S.scanAmt; S.sheet = null; begin({ title: "Djiwa Tentram Coffee", total: a, rows: [["Merchant", "Djiwa Tentram Coffee"], ["Metode", "QRIS"], ["Nominal", rp(a)]] }); };
window.payFlow = (k) => { const a = k === "send" ? +S.send.amt : +S.wd.amt + 2500; S.flow = { method: "wallet", status: k === "withdraw" ? "pending" : "ok", total: a, title: k === "send" ? "Kirim ke " + S.send.name : "Tarik dana", rows: k === "send" ? [["Penerima", S.send.name], ["Nomor HP", S.send.phone], ["Nominal", rp(+S.send.amt)]] : [["Bank", S.wd.bank + " " + S.wd.acc], ["Atas nama", S.wd.name], ["Nominal", rp(+S.wd.amt)], ["Biaya", rp(2500)]], okTitle: k === "send" ? "Saldo terkirim" : null }; S.pin = { v: "", mode: "pay", first: "", err: 0 }; S.sheet = "pin"; render(false); };
window.confirmPay = () => { const f = S.flow, short = S.bal < f.total; if (short || f.method === "qris") { f.method = "qris"; S.sheet = null; S.stack.push({ v: S.view, p: S.p, tab: S.tab }); S.view = "qris"; S.p = { amt: f.total }; render(); } else { S.pin = { v: "", mode: "pay", first: "", err: 0 }; S.sheet = "pin"; render(false); } };
window.pinKey = (mode, k) => {
  const P = S.pin; P.err = 0; if (k === "del") P.v = P.v.slice(0, -1); else if (P.v.length < 6) P.v += k; render(false);
  if (P.v.length < 6) return;
  setTimeout(() => {
    if (mode === "create") { P.first = P.v; P.v = ""; go("pin-confirm"); }
    else if (mode === "confirm") { if (P.v === P.first || true) { P.v = ""; go("bio"); } }
    else { if (P.v === "111111") { P.err = 1; P.v = ""; render(false); return; } const f = S.flow; if (f.method === "wallet") S.bal = Math.max(0, S.bal - f.total); P.v = ""; S.sheet = null; S.stack = []; S.view = "result"; S.p = {}; render(); }
  }, 180);
};

